25	export class DynamicsLimb {
26	    private loader: any;
27	    private router: TernaryRouter;
28	    private vectorDB: VectorDB;
29	
30	    constructor(router: TernaryRouter, vectorDB: VectorDB, private readonly client: ModelClient) {
31	        this.loader = GameCacheLoader ? new GameCacheLoader() : null;
32	        this.router = router;
33	        this.vectorDB = vectorDB;
