36	    public async healthCheck(): Promise<{ online: boolean; details: string }> {
37	        const loaderHealth = !!this.loader;
38	        return {
39	            online: loaderHealth,
40	            details: `Dynamics: ${loaderHealth ? 'ONLINE' : 'OFFLINE'} (Archive 21 mapped)`
41	        };
