44	    public async extractDynamics(spotAnimId: number): Promise<Result<PedagogyProfile>> {
45	        const state = this.router.temporalState;
46	        logger.info({ spotAnimId, state }, 'Extracting Dynamic Profile');
47	
48	        if (state === 'PAST') {
49	            const cached = this.vectorDB.queryLocal(`dynamic-${spotAnimId}`);
50	            if (cached.ok && cached.value) {
51	                return ok(cached.value.metadata as PedagogyProfile);
52	            }
53	        }
54	
55	        try {
56	            if (!this.loader || !parse || !cacheMajors) return err(new Error('DynamicsLimb: rsmv substrates not available.'));
57	            const buffer = await this.loader.getFile(cacheMajors.spotanims, spotAnimId);
58	            if (!buffer) return err(new Error(`SpotAnim ${spotAnimId} not found in cache.`));
59	
60	            const spotAnim = (parse as any).spotAnims.read(buffer, this.loader);
61	
62	            const profile: PedagogyProfile = {
63	                id: spotAnimId.toString(),
64	                name: `SpotAnim_${spotAnimId}`,
65	                type: 'DYNAMIC',
66	                metrics: {
67	                    polyCount: 0,
68	                    vertexCount: 0,
69	                    boneCount: 0,
70	                    materialComplexity: spotAnim.replace_materials?.length || 0,
71	                    rigLogic: spotAnim.sequence ? 'SKELETAL' : 'STATIC'
72	                },
73	                semantics: {
74	                    role: `Dynamic world effect link. Mesh: ${spotAnim.model}. Sequence: ${spotAnim.sequence}.`,
75	                    intent: 'world_event_particle_template'
76	                },
77	                timestamp: Date.now()
78	            };
79	
80	            return ok(profile);
81	        } catch (e) {
82	            logger.error({ spotAnimId, error: (e as Error).message }, 'Dynamic extraction failed');
83	            return err(new Error(`Dynamic extraction failed: ${(e as Error).message}`));
84	        }
85	    }
86	
87	    public close(): void {
88	        if (this.loader && typeof this.loader.close === 'function') {
89	            this.loader.close();
90	        }
91	    }
92	}
