1	import Database from 'better-sqlite3';
2	import * as fs from 'fs';
3	import * as path from 'path';
4	import { type Result, ok, err, YaoState } from '../../core/models.js';
5	import { HEXAGRAM_REGISTRY } from '../../core/HexagramDefinitions.js';
6	import { createLogger } from "../../utils/logger.js";
7	import { HexagramManager } from '../../routing/HexagramManager.js';
8	import { schema } from './EntitySchema.js';
9	import { getSovereignRoot } from '../../utils/SovereignPathResolver.js';
10	
11	const logger = createLogger('EntityLimb');
12	
13	/**
14	 * EntityLimb - Persistent Actor Management (Attention & Reinforcement Edition)
15	 * Manages identity, pedagogy, and dynamic behavioral bias through weighted experiences.
16	 */
17	export class EntityLimb {
18	    private static instance: EntityLimb | undefined;
19	    private db: Database.Database;
20	
21	    public static getInstance(): EntityLimb {
22	        if (!this.instance) {
23	            this.instance = new EntityLimb();
24	        }
25	        return this.instance;
26	    }
27	
28	    public static resetInstance(): void {
29	        if (process.env.NODE_ENV === 'production') {
30	            throw new Error('resetInstance is forbidden in production');
31	        }
32	        this.instance = undefined;
33	    }
34	
35	    private constructor() {
36	        if (EntityLimb.instance) {
37	            throw new Error('Singleton violation: use EntityLimb.getInstance()');
38	        }
39	        const root = getSovereignRoot();
40	        const dbPath = path.join(root, 'memory', 'memory.db');
41	        const dbDir = path.dirname(dbPath);
42	
43	        try {
44	            if (!fs.existsSync(dbDir)) {
45	                fs.mkdirSync(dbDir, { recursive: true });
46	            }
47	            this.db = new Database(dbPath);
48	            this.db.exec(schema);
49	
50	            // Migration: Add reinforcement column if it doesn't exist
51	            try {
52	                this.db.exec(`ALTER TABLE memories ADD COLUMN reinforcement REAL DEFAULT 1.0`);
53	                logger.info('Schema migration: Added reinforcement column.');
54	            } catch (e) {
55	                // Ignore if column already exists
56	            }
57	
58	            // Migration: Add player_identity table
59	            try {
60	                this.db.exec(`
61	                    CREATE TABLE IF NOT EXISTS player_identity (
62	                        id TEXT PRIMARY KEY,
63	                        name TEXT NOT NULL,
64	                        stats_json TEXT,
65	                        model_path TEXT,
66	                        updated_at INTEGER
67	                    );
68	                `);
69	            } catch (e) {
70	                logger.error({ e }, 'Failed to create player_identity table.');
71	            }
72	
73	            logger.info({ dbPath }, 'Entity persistence layer initialized.');
74	        } catch (err: any) {
75	            logger.error({ err }, 'Failed to initialize entity database.');
76	            throw err;
77	        }
78	    }
79	
80	    /**
81	     * registerEntity - Anchors identity and pedagogy profile to the persistent substrate.
82	     */
83	    public async registerEntity(profile: any): Promise<Result<string>> {
84	        const now = Date.now();
85	        const id = profile.id;
86	
87	        try {
88	            const registerStmt = this.db.prepare(`
89	                INSERT INTO entities (id, type, name, created_at, updated_at)
90	                VALUES (?, ?, ?, ?, ?)
91	                ON CONFLICT(id) DO UPDATE SET
92	                    updated_at=excluded.updated_at
93	            `);
94	
95	            const pedagogyStmt = this.db.prepare(`
96	                INSERT INTO pedagogy (entity_id, profile_json, updated_at)
97	                VALUES (?, ?, ?)
98	                ON CONFLICT(entity_id) DO UPDATE SET
99	                    profile_json=excluded.profile_json,
100	                    updated_at=excluded.updated_at
101	            `);
102	
103	            this.db.transaction(() => {
104	                registerStmt.run(id, profile.type, profile.name ?? null, now, now);
105	                pedagogyStmt.run(id, JSON.stringify(profile), now);
106	            })();
107	
108	            logger.info({ id }, 'Entity registered successfully.');
109	            return ok(id);
110	        } catch (err: any) {
111	            logger.error({ err, id }, 'Failed to register entity.');
112	            return err(new Error(`REGISTRATION_FAILED: ${err.message}`));
113	        }
114	    }
115	
116	    /**
117	     * addMemory - Injects a new memory and triggers pattern reinforcement.
118	     */
119	    public async addMemory(id: string, memory: any): Promise<Result<number>> {
120	        try {
121	            const contentStr = JSON.stringify(memory.content);
122	            const stmt = this.db.prepare(`
123	                INSERT INTO memories (entity_id, timestamp, type, content, weight, reinforcement)
124	                VALUES (?, ?, ?, ?, ?, ?)
125	            `);
126	
127	            const info = stmt.run(
128	                id,
129	                memory.timestamp ?? Date.now(),
130	                memory.type ?? 'observation',
131	                contentStr,
132	                memory.weight ?? 1.0,
133	                1.0
134	            );
135	
136	            const rowId = Number(info.lastInsertRowid);
137	
138	            // Reinforce similar past memories (Pattern Learning)
139	            // Use high-signal prefix for cheap clustering
140	            const pattern = contentStr.slice(0, 50);
141	            this.reinforceMemory(id, memory.type ?? 'observation', pattern);
142	
143	            return ok(rowId);
144	        } catch (err: any) {
145	            logger.error({ err, id }, 'Failed to add memory.');
146	            return err(new Error(`MEMORY_INSERT_FAILED: ${err.message}`));
147	        }
148	    }
149	
150	    /**
151	     * reinforceMemory - Strengthens the weight of repeated event patterns (unsupervised learning).
152	     */
153	    public reinforceMemory(id: string, type: string, pattern: string): Result<void> {
154	        try {
155	            const stmt = this.db.prepare(`
156	                UPDATE memories
157	                SET reinforcement = MIN(reinforcement + 0.25, 5.0)
158	                WHERE entity_id = ?
159	                  AND type = ?
160	                  AND content LIKE ?
161	            `);
162	            stmt.run(id, type, `%${pattern}%`);
163	            return ok(undefined);
164	        } catch (err: any) {
165	            logger.error({ err, id }, 'Failed to reinforce memory.');
166	            return err(new Error(`REINFORCE_FAILED: ${err.message}`));
167	        }
168	    }
169	
170	    /**
171	     * getTopMemories - Returns the most relevant experiences (Attention Engine).
172	     */
173	    private getTopMemories(id: string, limit = 20): any[] {
174	        const rows = this.db.prepare(`SELECT * FROM memories WHERE entity_id = ?`).all(id) as any[];
175	        const now = Date.now();
176	
177	        return rows
178	            .map(m => {
179	                const ageMs = now - m.timestamp;
180	                const decay = Math.exp(ageMs / (1000 * 60 * 60 * 24)); // Daily decay
181	                const score = ((m.weight ?? 1.0) * (m.reinforcement ?? 1.0)) / decay;
182	                
183	                return {
184	                    ...m,
185	                    content: JSON.parse(m.content),
186	                    score
187	                };
188	            })
189	            .sort((a, b) => b.score - a.score)
190	            .slice(0, limit);
191	    }
192	
193	    /**
194	     * updateVibeFromMemory - Mutates the entity's emotional state based on interaction type.
195	     */
196	    public async updateVibeFromMemory(id: string, memory: any): Promise<Result<any>> {
197	        const now = Date.now();
198	        try {
199	            const existing = this.db.prepare(`SELECT state_json FROM vibe_state WHERE entity_id = ?`).get(id) as any;
200	            const vibe = existing 
201	                ? JSON.parse(existing.state_json) 
202	                : { aggression: 0, affinity: 0, fear: 0, curiosity: 0, greed: 0, fatigue: 0 };
203	
204	            const weight = memory.weight ?? 1.0;
205	
206	            let yaoState = YaoState.YoungYin;
207	            let msg = '';
208	
209	            switch (memory.type) {
210	                case 'combat':
211	                    vibe.aggression = Math.min((vibe.aggression || 0) + 0.1 * weight, 5.0);
212	                    vibe.fatigue = Math.min((vibe.fatigue || 0) + 0.05 * weight, 5.0);
213	                    yaoState = YaoState.OldYang;
214	                    msg = `Entity [${id}] exhibited combat/aggression vibe shift.`;
215	                    break;
216	                case 'skilling':
217	                case 'mining':
218	                case 'fishing':
219	                    vibe.curiosity = Math.min((vibe.curiosity || 0) + 0.15 * weight, 5.0);
220	                    vibe.fatigue = Math.min((vibe.fatigue || 0) + 0.1 * weight, 5.0);
221	                    yaoState = YaoState.YoungYang;
222	                    msg = `Entity [${id}] exhibited constructive skilling vibe shift.`;
223	                    break;
224	                case 'drop':
225	                case 'reward':
226	                    vibe.greed = Math.min((vibe.greed || 0) + 0.2 * weight, 5.0);
227	                    vibe.affinity = Math.min((vibe.affinity || 0) + 0.1 * weight, 5.0);
228	                    yaoState = YaoState.YoungYin;
229	                    msg = `Entity [${id}] received a drop/reward vibe shift.`;
230	                    break;
231	                case 'threat':
232	                    vibe.fear = Math.min((vibe.fear || 0) + 0.15 * weight, 5.0);
233	                    yaoState = YaoState.OldYang;
234	                    msg = `Entity [${id}] exhibited aggressive/threat vibe shift.`;
235	                    break;
236	            }
237	
238	            if (msg) {
239	                const hexManager = HexagramManager.getInstance();
240	                await hexManager.pushLine({
241	                    lineIndex: 0,
242	                    importance: weight,
243	                    title: `Vibe Resonance: ${id}`,
244	                    content: msg,
245	                    state: yaoState
246	                });
247	            }
248	
249	            // Passive metabolic recovery in idle/rest is handled by decay or explicit rest actions
250	            // but we can add a small passive recovery here if needed.
251	
252	            this.db.prepare(`
253	                INSERT INTO vibe_state (entity_id, state_json, updated_at)
254	                VALUES (?, ?, ?)
255	                ON CONFLICT(entity_id) DO UPDATE SET
256	                    state_json = excluded.state_json,
257	                    updated_at = excluded.updated_at
258	            `).run(id, JSON.stringify(vibe), now);
259	
260	            return ok(vibe);
261	        } catch (err: any) {
262	            logger.error({ err, id }, 'Failed to update vibe state.');
263	            return err(new Error(`VIBE_UPDATE_FAILED: ${err.message}`));
264	        }
265	    }
266	
267	    /**
268	     * getEntityState - Retrieves the integrated snapshot dominated by Attention and Vibe.
269	     */
270	    public async getEntityState(id: string): Promise<Result<any>> {
271	        try {
272	            const entity = this.db.prepare(`SELECT * FROM entities WHERE id = ?`).get(id);
273	            if (!entity) return err(new Error(`ENTITY_NOT_FOUND: ${id}`));
274	
275	            const pedagogy = this.db.prepare(`SELECT profile_json FROM pedagogy WHERE entity_id = ?`).get(id);
276	            const memories = this.getTopMemories(id, 20);
277	            const vibeSnapshot = this.db.prepare(`SELECT state_json FROM vibe_state WHERE entity_id = ?`).get(id) as any;
278	
279	            return ok({
280	                entity,
281	                pedagogy: pedagogy ? JSON.parse((pedagogy as any).profile_json) : null,
282	                attention: memories, // Prioritized over history
283	                vibe: vibeSnapshot ? JSON.parse(vibeSnapshot.state_json) : { aggression: 0, affinity: 0, fear: 0, curiosity: 0, greed: 0, fatigue: 0 }
284	            });
285	        } catch (err: any) {
286	            logger.error({ err, id }, 'Failed to retrieve entity state.');
287	            return err(new Error(`STATE_RETRIEVAL_FAILED: ${err.message}`));
288	        }
289	    }
290	
291	    public async healthCheck(): Promise<{ online: boolean; details: string }> {
292	        if (!this.db) return { online: false, details: 'Entity Database not initialized.' };
293	        try {
294	            const row = this.db.prepare('SELECT count(*) as count FROM entities').get() as { count: number };
295	            return { online: true, details: `Entity Substrate: ONLINE (${row.count} active entities)` };
296	        } catch (e) {
297	            return { online: false, details: `Entity Substrate ERROR: ${(e as Error).message}` };
298	        }
