300	
301	    /**
302	     * decideAction - Core Behavioral Engine.
303	     * Maps the entity's vibe state and prioritized memories to a specific action and Yao state.
304	     */
305	    public async decideAction(id: string): Promise<Result<{ action: string, yao: YaoState, reasoning: string }>> {
306	        const stateRes = await this.getEntityState(id);
307	        if (!stateRes.ok) return err(stateRes.error);
308	
309	        const { vibe, attention } = stateRes.value;
310	        let action = 'idle';
311	        let yao = YaoState.YoungYin; // Default: Meditation/Reflection
312	        let reasoning = 'Maintaining baseline stability.';
313	
314	        // 1. Check for Critical Fatigue (Old Yin)
315	        if (vibe.fatigue > 3.0) {
316	            action = 'metabolic_rest';
317	            yao = YaoState.OldYin; // Deep recovery
318	            reasoning = `High fatigue (${vibe.fatigue.toFixed(2)}) detected. Initiating metabolic rest cycle.`;
319	        }
320	        // 2. Check for Economic Drive (Young Yang -> Old Yang if extreme)
321	        else if (vibe.greed > 1.5) {
322	            action = 'profit_hunt';
323	            yao = vibe.greed > 3.0 ? YaoState.OldYang : YaoState.YoungYang;
324	            reasoning = 'High wealth potential detected. Prioritizing economic gain.';
325	        }
326	        // 3. Check for Skill Growth (Young Yang)
327	        else if (vibe.curiosity > 1.0) {
328	            action = 'skilling_loop';
329	            yao = YaoState.YoungYang;
330	            reasoning = 'Skill curiosity peak. Engaging developmental loops.';
331	        }
332	        // 4. Check for Aggressive Bias (Old Yang)
333	        else if (vibe.aggression > 1.5) {
334	            action = 'combat_grind';
335	            yao = YaoState.OldYang;
336	            reasoning = 'Aggression levels maintained. Kinetic expansion favored.';
337	        } 
338	        // 5. Factor in specific "Attention" memories for state switching
339	        const recentProfit = attention.some((m: any) => m.type === 'drop');
340	        if (recentProfit && vibe.greed > 1.0 && action === 'skilling_loop') {
341	            action = 'profit_hunt';
342	            reasoning = 'Recent profit event detected. Diverting from skills to wealth maximization.';
343	        }
344	
345	        return ok({ action, yao, reasoning });
346	    }
347	
348	    /**
349	     * executeAction - Closes the cognitive loop.
350	     * Records the action taken as a memory, reinforcing the behavioral pattern.
351	     */
352	    public async executeAction(id: string, action: string): Promise<Result<void>> {
353	        const timestamp = Date.now();
354	        const type = 'action';
355	        const pattern = `ACTION_TAKEN:${action.toUpperCase()}`;
356	        
357	        // Log the decision as a new memory
358	        const addRes = await this.addMemory(id, { type, content: pattern, weight: 1.2 });
