63	    private executeJustificationQuery(q: EpistemicQuery): QueryResponse {
64	        const kernel = EpistemicTransitionKernel.getInstance();
65	        const proofs = kernel.getProofLog();
66	        const chain: EpistemicProof[] = [];
67	        
68	        // 1. Recursive Proof Search
69	        let currentArtifactId = q.targetId;
70	        const maxDepth = q.depth || 10;
71	
72	        for (let i = 0; i < maxDepth; i++) {
73	            const proof = proofs.find(p => p.artifactId === currentArtifactId);
74	            if (!proof) break;
75	
76	            chain.push(proof);
77	            
78	            // If we've reached a substrate grounding proof, we're done.
79	            if (proof.rule === 'SUBSTRATE_GROUNDING_MANDATE') break;
80	
81	            // Follow the parent link
82	            if (!proof.parentArtifactId) break;
83	            currentArtifactId = proof.parentArtifactId;
84	        }
85	
86	        return {
87	            query: q,
88	            status: chain.length > 0 ? 'VERIFIED' : 'INCONCLUSIVE',
89	            confidence: chain.length > 0 ? 1.0 : 0.0,
90	            proofChain: chain,
