183	    /**
184	     * evaluateCompositeCondition - Evaluates a set of conditions using AND/OR logic.
185	     */
186	    public async evaluateCompositeCondition(
187	        condition: CompositeCondition,
188	        context: GameState
189	    ): Promise<boolean> {
190	        if (condition.type === 'composite_and') {
191	            for (const cond of condition.conditions) {
192	                const met = await this.evaluateStringCondition(cond, context);
193	                if (!met) return false;
194	            }
195	            return true;
196	        }
197	        if (condition.type === 'composite_or') {
198	            for (const cond of condition.conditions) {
199	                const met = await this.evaluateStringCondition(cond, context);
200	                if (met) return true;
201	            }
202	            return false;
203	        }
204	        return false;
205	    }
