207	    /**
208	     * evaluateStringCondition - Parses and evaluates a string-based condition.
209	     * Supports varbits and basic functional checks.
210	     */
211	    public async evaluateStringCondition(
212	        condition: string,
213	        context: GameState
214	    ): Promise<boolean> {
215	        // Varbit matching: varbit_1234 == 1
216	        const varbitMatch = condition.match(/varbit_(\d+)\s*(==|!=|<|>|<=|>=)\s*(\d+)/);
217	        if (varbitMatch) {
218	            const [_, idStr, operator, valStr] = varbitMatch;
219	            const id = parseInt(idStr);
220	            const target = parseInt(valStr);
221	            const actual = context.varbits.get(id) || 0;
222	            switch (operator) {
223	                case '==': return actual === target;
224	                case '!=': return actual !== target;
225	                case '<': return actual < target;
226	                case '>': return actual > target;
227	                case '<=': return actual <= target;
228	                case '>=': return actual >= target;
229	            }
230	        }
231	
232	        // Inventory matching: has_item(12519) == true
233	        const itemMatch = condition.match(/has_item\((\d+)\)\s*==\s*(true|false)/);
234	        if (itemMatch) {
235	            const [_, idStr, stateStr] = itemMatch;
236	            const itemId = parseInt(idStr);
237	            const target = stateStr === 'true';
238	            
239	            // Query the primary avatar's 28-slot inventory
240	            const avatar = context.players.get('POG2_Sovereign');
241	            const has = avatar?.inventory.some(i => i?.id === itemId) || false;
242	            return has === target;
243	        }
244	
245	
246	        // Functional check matching: is_follower_active(player, 7015) == true
247	        if (condition.includes('is_follower_active')) {
248	            const match = condition.match(/is_follower_active\(.*,\s*(\d+)\)\s*==\s*true/);
249	            if (match) {
250	                const entityId = parseInt(match[1]);
251	                for (const npcs of context.npcSpatialIndex.values()) {
252	                    if (npcs.some(n => n.id === entityId)) return true;
253	                }
254	            }
255	            return false;
256	        }
257	
258	        // Level check: has_level("Attack", 90) == true
259	        const levelMatch = condition.match(/has_level\("(.*)",\s*(\d+)\)\s*==\s*(true|false)/);
260	        if (levelMatch) {
261	            const [_, skillName, levelStr, targetState] = levelMatch;
262	            const reqLevel = parseInt(levelStr);
263	            const target = targetState === 'true';
264	            
265	            const avatar = context.players.get('POG2_Sovereign');
266	            if (!avatar) return !target;
267	
268	            // Find skill by name
269	            const skill = Object.values(avatar.skills).find(s => s.name.toLowerCase() === skillName.toLowerCase());
270	            const has = (skill?.level || 0) >= reqLevel;
271	            return has === target;
272	        }
273	
274	        // Equipment Gating: can_equip(1289) == true
275	        const equipMatch = condition.match(/can_equip\((\d+)\)\s*==\s*(true|false)/);
276	        if (equipMatch) {
277	            const [_, idStr, stateStr] = equipMatch;
278	            const itemId = parseInt(idStr);
279	            const target = stateStr === 'true';
280	            
281	            const avatar = context.players.get('POG2_Sovereign');
282	            if (!avatar) return !target;
283	
284	            const res = this.canEquip(itemId, avatar);
285	            return res.ok === target;
286	        }
287	
288	        return false;
289	    }
