324	    /**
325	     * validateAbility - Checks adrenaline and resource costs for Necromancy abilities.
326	     * Grounded in necromancy_logic.json.
327	     */
328	    public validateAbility(abilityId: string, avatar: SovereignAvatar): Result<boolean> {
329	        if (!this.pedagogy) return ok(true);
330	        const logic = this.pedagogy.getNecromancyLogic();
331	        if (!logic) return ok(true);
332	
333	        const ability = logic.abilities[abilityId];
334	        if (!ability) return err(new Error(`Unknown ability: ${abilityId}`));
335	
336	        // 1. Check Adrenaline
337	        const adrenaline = avatar.metadata?.combat_state?.adrenaline || 0;
338	        if (ability.adrenaline < 0 && adrenaline < Math.abs(ability.adrenaline)) {
339	            return err(new Error(`Insufficient Adrenaline: ${Math.abs(ability.adrenaline)}% required.`));
340	        }
341	
342	        // 2. Check Resources (Ectoplasm)
343	        if (ability.cost && ability.cost.includes('Ectoplasm')) {
344	            const ectoMatch = ability.cost.match(/(\d+)\s*Ectoplasm/);
345	            const reqEcto = ectoMatch ? parseInt(ectoMatch[1]) : 1;
346	            const hasEcto = avatar.inventory.find(i => i?.id === 57167)?.amount || 0;
347	            if (hasEcto < reqEcto) {
348	                return err(new Error(`Insufficient Ectoplasm: ${reqEcto} required.`));
349	            }
350	        }
351	
352	        return ok(true);
353	    }
