42	    private initializeObjectives(): void {
43	        // 1. Basic Skill Milestones
44	        const skills: string[] = ['Attack', 'Strength', 'Defense', 'Ranged', 'Prayer', 'Magic'];
45	        skills.forEach((skill: string) => {
