91	     * @param avatar The current state of the SovereignAvatar.
92	     * @returns An array of uncompleted SovereignObjective objects, sorted by priority.
93	     */
94	    public getActiveObjectives(avatar: SovereignAvatar): SovereignObjective[] {
95	        // Filter out completed objectives
96	        this.syncState(avatar);
97	        return this.objectives
98	            .filter((o: SovereignObjective) => !o.isCompleted)
99	            .sort((a: SovereignObjective, b: SovereignObjective) => a.priority - b.priority);
100	    }
