102	    /**
103	     * syncState - Updates completion status based on avatar state.
104	     * @param avatar The current state of the SovereignAvatar.
105	     *
106	     * ASSUMPTIONS about SovereignAvatar structure (since models.js is not editable):
107	     * - avatar.x: number, avatar.y: number (for current position)
108	     * - avatar.skills: Array of objects, where each object has a 'level' property (e.g., { level: number, xp: number }).
109	     *   The index of the array corresponds to the skill ID from skillMap.
110	     * - avatar.quests: Optional object with a 'quests' property, which is a Record<string, string>
111	     *   mapping quest IDs to their status (e.g., { quests: { 'quest_cooks_assistant': 'COMPLETED' } }).
112	     */
113	    private syncState(avatar: SovereignAvatar): void {
114	        this.objectives.forEach((o: SovereignObjective) => {
115	            if (o.isCompleted) {
116	                return;
117	            }
118	
119	            if (o.type === 'SKILL') {
120	                const parts = o.name.split(' ');
121	                // Ensure skillName is extracted safely
122	                const skillName = parts.length > 1 ? parts[1] : undefined;
123	
124	                if (skillName) {
125	                    // Resolve skill ID (simplified mapping)
126	                    const skillMap: Record<string, number> = { 'Attack': 1, 'Strength': 2, 'Defense': 5, 'Ranged': 3, 'Prayer': 7, 'Magic': 4 };
127	                    const id = skillMap[skillName];
128	
129	                    // Check if id is a valid key for avatar.skills object and if the skill object exists
130	                    if (typeof id === 'number' && avatar.skills && avatar.skills[id]) {
131	                        const skill = avatar.skills[id];
132	                        // Ensure skill object exists and has a level property
133	                        if (skill && typeof skill.level === 'number' && skill.level >= 5) {
134	                            this.completeObjective(o.id);
135	                        }
136	                    }
137	                }
138	            }
139	
140	            if (o.type === 'DISCOVERY') {
141	                const resolver = LocationResolver.getInstance();
142	                const targetName = o.name.replace('Discover ', '');
143	                const targetCoord = resolver.resolveLocationByName(targetName);
144	                
145	                if (targetCoord) {
146	                    const dist = Math.abs(avatar.x - targetCoord.x) + Math.abs(avatar.y - targetCoord.y);
147	                    if (dist < 10 && avatar.plane === (targetCoord.plane ?? 0)) {
