87	class SubstrateLoader {
88	    private static cache: Map<string, any> = new Map();
89	
90	    static load<T>(path: string): T | null {
91	        if (this.cache.has(path)) return this.cache.get(path) as T;
92	        if (!existsSync(path)) { logger.warn({ path }, 'Substrate file not found'); return null; }
93	        try {
94	            const data = JSON.parse(readFileSync(path, 'utf8'));
95	            this.cache.set(path, data);
96	            return data as T;
97	        } catch (e) {
98	            logger.error({ path, err: e }, 'Failed to load substrate');
99	            return null;
100	        }
101	    }
102	}
