149	    // ─── Sandbox Allocation ───
150	    // Finds an unused mapsquare outside all known populated mapzones
151	
152	    private allocateSandbox(): SandboxRegion {
153	        const zones = this.loadMapZones();
154	        const usedSquares = new Set<string>();
155	
156	        // Collect all occupied mapsquares from mapzone bounds
157	        for (const zone of Object.values(zones)) {
158	            if (!zone.bounds) continue;
159	            for (const bound of zone.bounds) {
160	                const src = bound.src || bound;
161	                if (!src.xstart) continue;
162	                const msXStart = Math.floor(src.xstart / 64);
163	                const msXEnd = Math.floor(src.xend / 64);
164	                const msZStart = Math.floor(src.zstart / 64);
165	                const msZEnd = Math.floor(src.zend / 64);
166	                for (let mx = msXStart; mx <= msXEnd; mx++) {
167	                    for (let mz = msZStart; mz <= msZEnd; mz++) {
168	                        usedSquares.add(`${mx}_${mz}`);
169	                    }
170	                }
171	            }
172	        }
173	
174	        // Search for an empty mapsquare in the "sandbox range" (high coordinates)
175	        // RS3 world is roughly 0-100 on each axis, instances are typically 150+
176	        let targetX = 90, targetZ = 90;
177	        for (let x = 90; x < 200; x++) {
178	            for (let z = 90; z < 200; z++) {
179	                if (!usedSquares.has(`${x}_${z}`)) {
180	                    targetX = x; targetZ = z;
181	                    break;
182	                }
183	            }
184	            if (targetX !== 90 || targetZ !== 90) break;
185	        }
186	
187	        logger.info({ mapsquare: `${targetX}_${targetZ}` }, 'Allocated sandbox mapsquare');
188	
189	        // Generate flat walkable terrain with border walls
190	        const collision: Record<string, number> = {};
191	        const heightmap: number[] = new Array(64 * 64).fill(0);
192	
193	        for (let lx = 0; lx < 64; lx++) {
194	            for (let lz = 0; lz < 64; lz++) {
195	                const wx = targetX * 64 + lx;
196	                const wz = targetZ * 64 + lz;
197	                // Border walls (2-tile thick perimeter)
198	                const isBorder = lx < 2 || lx > 61 || lz < 2 || lz > 61;
199	                collision[`0_${wx}_${wz}`] = isBorder ? 1 : 0;
200	            }
201	        }
202	
203	        return {
204	            mapsquareX: targetX,
205	            mapsquareZ: targetZ,
206	            worldBounds: {
207	                xMin: targetX * 64, xMax: targetX * 64 + 63,
208	                zMin: targetZ * 64, zMax: targetZ * 64 + 63
209	            },
210	            collisionMatrix: collision,
211	            npcs: [],
212	            objects: [],
213	            heightmap
214	        };
215	    }
