290	    private calibrateFromExisting(difficulty: string): { skills: any[], xpRewards: any[], questPoints: number } {
291	        const { quests } = this.loadQuests();
292	        const similar = quests.filter(q =>
293	            q.skillRequirements && q.skillRequirements.length > 0 &&
294	            q.progressStates && q.progressStates.length >= 2
295	        );
296	
297	        if (similar.length === 0) {
298	            return { skills: [], xpRewards: [{ skill: 'Constitution', amount: 1000 }], questPoints: 1 };
299	        }
300	
301	        // Average skill levels from similar-difficulty quests
302	        const avgLevel = Math.round(
303	            similar.flatMap(q => q.skillRequirements.map((s: any) => s.level))
304	                .reduce((a: number, b: number) => a + b, 0) / Math.max(1, similar.flatMap(q => q.skillRequirements).length)
305	        );
306	
307	        const difficultyScale: Record<string, number> = {
308	            'Novice': 0.3, 'Intermediate': 0.6, 'Experienced': 0.8, 'Master': 1.0, 'Grandmaster': 1.2
309	        };
310	        const scale = difficultyScale[difficulty] || 0.6;
311	        const scaledLevel = Math.round(avgLevel * scale);
312	        const xpAmount = Math.round(1000 * scale * scale);
313	
314	        return {
315	            skills: [{ skill: 'Attack', skillId: 0, level: scaledLevel }],
316	            xpRewards: [{ skill: 'Attack', amount: xpAmount }],
317	            questPoints: Math.max(1, Math.round(5 * scale))
318	        };
319	    }
