325	    public async forgeQuest(
326	        title: string,
327	        scenes: StoryboardScene[],
328	        difficulty: string = 'Intermediate'
329	    ): Promise<Result<QuestPackage>> {
330	        logger.info({ title, scenes: scenes.length, difficulty }, '⚒️ FORGING production quest package...');
331	
332	        // 1. Allocate spatial sandbox
333	        const sandbox = this.allocateSandbox();
334	        const center = {
335	            x: sandbox.worldBounds.xMin + 32,
336	            y: sandbox.worldBounds.zMin + 32,
337	            plane: 0
338	        };
339	
340	        // 2. Build quest stages from scenes with spatial grounding
341	        const stages: QuestStage[] = [];
342	        const questItems: GroundedItem[] = [];
343	        const stageOffset = 0;
344	
345	        for (let i = 0; i < scenes.length; i += 3) {
346	            const batch = scenes.slice(i, i + 3);
347	            const stageIndex = stages.length + 1;
348	
349	            // Place stage NPCs in a ring around center
350	            const angle = (stageIndex / Math.ceil(scenes.length / 3)) * 2 * Math.PI;
351	            const radius = 10 + stageIndex * 3;
352	            const stageCoord = {
353	                x: Math.round(center.x + Math.cos(angle) * radius),
354	                y: Math.round(center.y + Math.sin(angle) * radius),
355	                plane: 0
356	            };
357	
358	            // Ground an NPC for this stage
359	            const npcRole = stageIndex === 1 ? 'quest_giver' : (stageIndex === stages.length ? 'antagonist' : 'ally');
360	            const npcName = batch[0]?.speaker || `${title} NPC ${stageIndex}`;
361	            const npc = this.groundNPCForRole(npcRole, npcName, stageCoord);
362	
363	            // Build dialogue from scene text
364	            const dialogue: QuestDialogue[] = batch
365	                .filter(s => s.description)
366	                .map(s => ({
367	                    speaker: s.speaker || npcName,
368	                    text: s.description.slice(0, 200)
369	                }));
370	            npc.dialogue = dialogue;
371	
372	            sandbox.npcs.push(npc);
373	
374	            // Ground any items mentioned
375	            const itemNames = batch.filter(s => s.dataType === 'item' && s.modelId).map(s => s.description.split('.')[0]);
376	            const stageItems = itemNames.map(n => this.groundItem(n, true));
377	            questItems.push(...stageItems);
378	
379	            // Open the collision around the NPC spawn point
380	            for (let dx = -2; dx <= 2; dx++) {
381	                for (let dz = -2; dz <= 2; dz++) {
382	                    sandbox.collisionMatrix[`0_${stageCoord.x + dx}_${stageCoord.y + dz}`] = 0;
383	                }
384	            }
385	
386	            stages.push({
387	                index: stageIndex,
388	                title: `Stage ${stageIndex}: ${batch[0]?.description.split('.')[0] || 'Continue'}`,
389	                description: batch.map(s => s.description).join(' '),
390	                objectives: batch.map(s => s.description.slice(0, 100)),
391	                npcs: [npc.id],
392	                items: stageItems.map(i => i.id),
393	                location: stageCoord,
394	                dialogue
395	            });
396	        }
397	
398	        // 3. Place environmental objects (entrance, exit, scenery)
399	        const entranceObj: GroundedObject = {
400	            id: 70000 + Math.floor(Math.random() * 5000),
401	            name: 'Quest Portal',
402	            type: 'scenery',
403	            modelRef: 10000, // Generic portal reference
404	            coord: { x: sandbox.worldBounds.xMin + 5, y: sandbox.worldBounds.zMin + 32, plane: 0 },
405	            actions: ['Enter', 'Examine'],
406	            blocksMovement: false
407	        };
408	        sandbox.objects.push(entranceObj);
409	
410	        // 4. Calibrate difficulty from existing quest data
411	        const calibration = this.calibrateFromExisting(difficulty);
412	
413	        // 5. Allocate varbits for quest state machine
414	        const varbits = this.allocateVarbits(stages.length);
415	
416	        // 6. Build state machine transitions
417	        const stateMachine = stages.map((stage, i) => ({
418	            fromStage: i,
419	            toStage: i + 1,
420	            trigger: `complete_stage_${stage.index}`,
421	            varbitValue: i + 1
422	        }));
423	
424	        // 7. Assemble the QuestDefinition (matching quests.json schema)
425	        const quest: QuestDefinition = {
426	            id: `quest_forge_${title.toLowerCase().replace(/\s+/g, '_')}`,
427	            name: title,
428	            description: scenes[0]?.description.slice(0, 200) || title,
429	            author: 'Sovereign Organism POG2 — QuestForge',
430	            difficulty: difficulty as any,
431	            length: scenes.length > 15 ? 'Long' : scenes.length > 8 ? 'Medium' : 'Short',
432	            category: 4746,   // Quests category from substrate
433	            subcategory: 4748,
434	            runeScore: calibration.questPoints * 2,
435	            spriteId: 30108,
436	            isF2P: false,
437	            isHidden: false,
438	            requirements: {
439	                skills: calibration.skills,
440	                quests: [],
441	                items: questItems.filter(i => i.questItem).map(i => i.id)
442	            },
443	            rewards: {
444	                xp: calibration.xpRewards,
445	                items: questItems.filter(i => !i.questItem).map(i => ({ id: i.id, amount: 1 })),
446	                questPoints: calibration.questPoints,
447	                rewardText: `Congratulations! You have completed ${title}.`
448	            },
449	            stages
450	        };
451	
452	        // 8. Export the full package
453	        const exportPath = join(getPipelineRootPath(), 'quest-forge', title.replace(/\s+/g, '_').toLowerCase());
454	        if (!existsSync(exportPath)) mkdirSync(exportPath, { recursive: true });
455	
456	        const pkg: QuestPackage = { quest, sandbox, items: questItems, varbits, stateMachine, exportPath };
457	
458	        // Write all artifacts
459	        const dirs = ['spatial', 'entities', 'logic', 'rewards'];
460	        for (const d of dirs) {
461	            const dp = join(exportPath, d);
462	            if (!existsSync(dp)) mkdirSync(dp, { recursive: true });
463	        }
464	
465	        writeFileSync(join(exportPath, 'quest_definition.json'), JSON.stringify(quest, null, 2));
466	        writeFileSync(join(exportPath, 'spatial', 'sandbox_collision.json'), JSON.stringify({
467	            mapsquare: `${sandbox.mapsquareX}_${sandbox.mapsquareZ}`,
468	            bounds: sandbox.worldBounds,
469	            collision_matrix: sandbox.collisionMatrix,
470	            heightmap: sandbox.heightmap
471	        }, null, 2));
472	        writeFileSync(join(exportPath, 'spatial', 'npc_spawns.json'), JSON.stringify(sandbox.npcs, null, 2));
473	        writeFileSync(join(exportPath, 'spatial', 'object_placements.json'), JSON.stringify(sandbox.objects, null, 2));
474	        writeFileSync(join(exportPath, 'entities', 'items.json'), JSON.stringify(questItems, null, 2));
475	        writeFileSync(join(exportPath, 'entities', 'npcs.json'), JSON.stringify(sandbox.npcs, null, 2));
476	        writeFileSync(join(exportPath, 'logic', 'varbits.json'), JSON.stringify(varbits, null, 2));
477	        writeFileSync(join(exportPath, 'logic', 'state_machine.json'), JSON.stringify(stateMachine, null, 2));
478	        writeFileSync(join(exportPath, 'logic', 'dialogue_tree.json'), JSON.stringify(
479	            sandbox.npcs.map(n => ({ npcId: n.id, name: n.name, dialogue: n.dialogue })), null, 2));
480	        writeFileSync(join(exportPath, 'rewards', 'xp_grants.json'), JSON.stringify(quest.rewards.xp, null, 2));
481	        writeFileSync(join(exportPath, 'rewards', 'item_grants.json'), JSON.stringify(quest.rewards.items, null, 2));
482	
483	        logger.info({ exportPath, stages: stages.length, npcs: sandbox.npcs.length, items: questItems.length }, '✅ Quest package forged and exported.');
484	
485	        return ok(pkg);
486	    }
