73	    public async synthesizeFromScenes(
74	        title: string,
75	        scenes: StoryboardScene[],
76	        targetDifficulty: string = 'Intermediate'
77	    ): Promise<Result<QuestDefinition>> {
78	        logger.info({ title, scenesCount: scenes.length }, 'Synthesizing Quest Logic from Storyboard...');
79	
80	        // 1. Group scenes into "Stages" (logical chunks of objectives)
81	        const stages: QuestStage[] = [];
82	        let currentStage: QuestStage | null = null;
83	
84	        for (let i = 0; i < scenes.length; i++) {
85	            const scene = scenes[i];
86	            
87	            // New stage every 3 scenes, or if explicit location shift
88	            if (i % 3 === 0) {
89	                if (currentStage) stages.push(currentStage);
90	                currentStage = {
91	                    index: stages.length + 1,
92	                    title: `Stage ${stages.length + 1}: ${scene.description.split('.')[0]}`,
93	                    description: scene.description,
94	                    objectives: [scene.description],
95	                    npcs: scene.modelId && scene.dataType === 'npc' ? [scene.modelId] : [],
96	                    items: scene.modelId && scene.dataType === 'item' ? [scene.modelId] : [],
97	                    dialogue: []
98	                };
99	            } else if (currentStage) {
100	                currentStage.objectives.push(scene.description);
101	                if (scene.modelId && scene.dataType === 'npc') currentStage.npcs.push(scene.modelId);
102	                if (scene.modelId && scene.dataType === 'item') currentStage.items.push(scene.modelId);
103	            }
104	
105	            // Map character dialogue if speaker exists
106	            if (scene.speaker && scene.description.includes('"')) {
107	                const dialogueText = scene.description.match(/"([^"]+)"/)?.[1] || scene.description;
108	                currentStage?.dialogue.push({
109	                    speaker: scene.speaker,
110	                    text: dialogueText
111	                });
112	            }
113	        }
114	        if (currentStage) stages.push(currentStage);
115	
116	        // 2. Synthesize Meta-Logic (Requirements & Rewards) via LLM
117	        const metaPrompt = `
118	Synthesize AUTHENTIC RS3 Quest Metadata for "${title}"
119	Stages: ${JSON.stringify(stages.map(s => s.title))}
120	Summary: ${scenes[0]?.description} ... ${scenes[scenes.length-1]?.description}
121	
122	Logic: This is a classic "Romeo and Juliet" theme. 
123	Rewards MUST include items related to the narrative (e.g., Cadava Berries, Potion of Kadava).
124	Rewards MUST include RS3-appropriate XP amounts for an Intermediate quest (e.g., Cooking, Herblore).
125	
126	JSON format:
127	{
128	  "difficulty": "Intermediate",
129	  "length": "Medium",
130	  "requirements": {
131	    "skills": [{ "skill": "Cooking", "level": 5 }, { "skill": "Herblore", "level": 10 }],
132	    "items": [ { "id": 1951, "amount": 1 } ] 
133	  },
134	  "rewards": {
135	    "xp": [{ "skill": "Cooking", "amount": 1000 }, { "skill": "Herblore", "amount": 1000 }],
136	    "items": [{ "id": 1951, "amount": 3 }],
137	    "questPoints": 5
138	  }
139	}
140	        `;
141	
142	        const metaRes = await this.client.resilientCall({
143	            model: this.client.config.midPathModel,
144	            prompt: metaPrompt,
145	            format: 'json',
146	            tier: 'Executive'
147	        });
148	
149	        const meta = metaRes.ok ? JSON.parse(metaRes.value.response) : {
150	            difficulty: 'Intermediate',
151	            length: 'Medium',
152	            requirements: { skills: [], items: [] },
153	            rewards: { xp: [], items: [], questPoints: 1 }
154	        };
155	
156	        const definition: QuestDefinition = {
157	            id: `quest_${title.toLowerCase().replace(/\s+/g, '_')}`,
158	            name: title,
159	            author: 'Sovereign Organism POG2',
160	            isF2P: false,
161	            isHidden: false,
162	            category: 4746, // Default to "Quests" category from substrate
163	            spriteId: 30108, // Default Quest Sprite
164	            ...meta,
165	            stages
166	        };
167	
168	        return ok(definition);
169	    }
